-- Orion: first-time setup
-- Run ONCE in the Supabase SQL editor after the baseline migration, on a new project.
--
-- EDIT THESE TWO VALUES FIRST:
--   your business name, and the email domain you and your staff sign in with
--   (only people with an email on this domain can sign up).

DO $setup$
DECLARE
  v_business_name text := 'Your Business';     -- <== edit
  v_email_domain  text := 'yourbusiness.com';  -- <== edit (no @)
  v_org uuid := '00000000-0000-0000-0000-000000000001';
BEGIN
  VALUES (v_org, v_business_name, lower(regexp_replace(v_business_name, '[^a-zA-Z0-9]+', '-', 'g')), v_business_name)
  ON CONFLICT (id) DO NOTHING;

  VALUES (v_org, lower(v_email_domain), ARRAY['email','google','microsoft'], true)
  ON CONFLICT DO NOTHING;
END
$setup$;


